    tx1.send(10).unwrap();          // ✅ 发送不依赖 rx2
    let v = rx2.await.unwrap();
    println!("a got: {v}");
});

let b = tokio::spawn(async move {
    tx2.send(20).unwrap();          // ✅ 发送不依赖 rx1
    let v = rx1.await.unwrap();
    println!("b got: {v}");
});

tokio::join!(a, b);
