    <!-- ============ JavaScript ============ -->
    <script>
        // Navbar scroll effect
        const navbar = document.getElementById('navbar');
        const backToTop = document.getElementById('backToTop');

        window.addEventListener('scroll', () => {
            if (window.scrollY > 80) {
                navbar.classList.add('scrolled');
            } else {
                navbar.classList.remove('scrolled');
            }

            if (window.scrollY > 500) {
                backToTop.classList.add('visible');
            } else {
                backToTop.classList.remove('visible');
            }
        });

        // Back to top
        backToTop.addEventListener('click', () => {
            window.scrollTo({ top: 0, behavior: 'smooth' });
        });

        // Mobile menu toggle
        const mobileToggle = document.getElementById('mobileToggle');
        const navLinks = document.getElementById('navLinks');

        mobileToggle.addEventListener('click', () => {
            navLinks.classList.toggle('active');
        });

        // Close mobile menu on link click
        navLinks.querySelectorAll('a').forEach(link => {
            link.addEventListener('click', () => {
                navLinks.classList.remove('active');
            });
        });

        // Scroll animations
        const animateElements = document.querySelectorAll('.animate-on-scroll');

        const observer = new IntersectionObserver((entries) => {
            entries.forEach((entry, index) => {
                if (entry.isIntersecting) {
                    setTimeout(() => {
                        entry.target.classList.add('visible');
                    }, index * 100);
                    observer.unobserve(entry.target);
                }
            });
        }, {
            threshold: 0.1,
            rootMargin: '0px 0px -50px 0px'
        });

        animateElements.forEach(el => observer.observe(el));

        // Form submission
        document.getElementById('contactForm').addEventListener('submit', function(e) {
            e.preventDefault();

            const btn = this.querySelector('.submit-btn');
            const originalText = btn.textContent;

            btn.textContent = '提交中...';
            btn.style.opacity = '0.7';
            btn.disabled = true;

            setTimeout(() => {
                btn.textContent = '✓ 提交成功！';
                btn.style.background = 'linear-gradient(135deg, #4CAF50, #45a049)';
                btn.style.opacity = '1';

                setTimeout(() => {
                    btn.textContent = originalText;
                    btn.style.background = 'linear-gradient(135deg, var(--primary), var(--primary-dark))';
                    btn.disabled = false;
                    this.reset();
                }, 2500);
            }, 1500);
        });

        // Smooth scroll for anchor links
        document.querySelectorAll('a[href^="#"]').forEach(anchor => {
            anchor.addEventListener('click', function(e) {
                e.preventDefault();
                const target = document.querySelector(this.getAttribute('href'));
                if (target) {
                    const offset = 80;
                    const targetPosition = target.getBoundingClientRect().top + window.pageYOffset - offset;
                    window.scrollTo({
                        top: targetPosition,
                        behavior: 'smooth'
                    });
                }
            });
        });

        // Counter animation for stats
        function animateCounters() {
            const counters = document.querySelectorAll('.stat-number');
            counters.forEach(counter => {
                const text = counter.textContent;
                const hasPlus = text.includes('+');
                const hasPercent = text.includes('%');
                const target = parseInt(text);

                if (isNaN(target)) return;

                let current = 0;
                const increment = target / 60;
                const timer = setInterval(() => {
                    current += increment;
                    if (current >= target) {
                        current = target;
                        clearInterval(timer);
                    }
                    let display = Math.floor(current);
                    if (hasPlus) display += '+';
                    if (hasPercent) display += '%';
                    counter.textContent = display;
                }, 30);
            });
        }

        // Trigger counter animation when hero is visible
        const heroObserver = new IntersectionObserver((entries) => {
            entries.forEach(entry => {
                if (entry.isIntersecting) {
                    setTimeout(animateCounters, 500);
                    heroObserver.unobserve(entry.target);
                }
            });
        }, { threshold: 0.3 });

        heroObserver.observe(document.querySelector('.hero'));
    </script>
</body>
</html>
```

## 页面结构说明

这个落地页包含以下完整模块：

### 🎯 主要区块

| 区块 | 说明 |
|------|------|
| **导航栏** | 固定顶部，滚动时添加毛玻璃背景效果，含移动端汉堡菜单 |
| **Hero 横幅** | 大标题 + 数据统计 + CTA按钮 + 浮动卡片装饰 |
| **服务项目** | 6 个服务卡片，悬停动画效果 |
| **为什么选择我们** | 图文并排，核心优势列表 + 20 年经验徽章 |
| **施工流程** | 4 步流程，带编号圆点和连接线 |
| **工程案例** | 3 个项目卡片，悬停显示详情 overlay |
| **客户评价** | 3 条评价卡片，含评分星级和头像 |
| **CTA 横幅** | 行动召唤区，双按钮引导转化 |
| **联系表单** | 左侧联系信息 + 右侧报价表单 |
| **页脚** | 品牌信息、快速导航、版权声明 |

### ✨ 交互特效

- **滚动动画**：元素进入视口时 fadeInUp 显示
- **数字计数**：Hero 区统计数字从 0 递增动画
- **导航变色**：滚动超过 80px 时导航栏变为白色背景
- **卡片悬停**：服务卡片上移 + 顶部色条动画
- **表单提交**：模拟提交 loading 和成功状态
- **回到顶部**：滚动超过 500px 时显示
